mapper.select:
SELECT a.MOIM_ID ,a.MOIM_TITLE ,a.MOIM_DSCR ,a.MOIM_TITLE_EN ,a.MOIM_TITLE_JA ,a.MOIM_DSCR_EN ,a.MOIM_DSCR_JA ,a.MOIM_START_DT ,a.MOIM_END_DT ,d.USER_NM ,COALESCE(v.VISIT_CNT, 0) AS VISIT_CNT ,a.MAX_MEMBER ,COALESCE(m.MEMBER_CNT, 0) AS MEMBER_CNT ,c.CATE_CD ,c.CATE_NM ,e.AVG_SCORE
,(SELECT t1.FIRST_IMAGE FROM TB_TRMA_MOIM_CALENDAR cal LEFT JOIN TB_TRMA_TOUR_LIST t1 ON cal.TOUR_ID = t1.TOUR_ID WHERE cal.MOIM_ID = a.MOIM_ID ORDER BY cal.START_DT ASC, cal.RMKS ASC LIMIT 1) AS IMAGE_URL FROM TB_TRMA_MOIM_LIST a LEFT JOIN TB_TRMA_USER_INFO d ON a.CREATE_USER = d.USER_ID LEFT JOIN ( SELECT MOIM_ID, COUNT(USER_ID) AS MEMBER_CNT FROM TB_TRMA_MOIM_MEMBER GROUP BY MOIM_ID ) m ON a.MOIM_ID = m.MOIM_ID LEFT JOIN ( SELECT MOIM_ID, COUNT(VISIT_ID) AS VISIT_CNT FROM TB_TRMA_MOIM_VISIT_H GROUP BY MOIM_ID ) v ON a.MOIM_ID = v.MOIM_ID LEFT JOIN ( SELECT e.MOIM_ID, GROUP_CONCAT(e.CATE_CD ORDER BY e.CATE_CD) AS CATE_CD, GROUP_CONCAT(f.CMM_CM_NM ORDER BY f.CMM_CM_NM) AS CATE_NM FROM TB_TRMA_MOIM_CATE e LEFT JOIN TB_TRMA_CMM_CD_D f ON e.CATE_CD = f.CMM_CDV AND f.CMM_CD_ID = 'CATE_ID' AND f.USE_YN = 'Y' GROUP BY e.MOIM_ID ) c ON a.MOIM_ID = c.MOIM_ID
LEFT JOIN ( SELECT owner_id AS CREATE_USER, AVG(REVIEW_SCORE) AS AVG_SCORE FROM ( SELECT f1.REVIEW_ID, f1.REVIEW_SCORE, f2.CREATE_USER AS owner_id FROM TB_TRMA_MOIM_REVIEW f1 LEFT JOIN TB_TRMA_MOIM_LIST f2 ON f1.MOIM_ID = f2.MOIM_ID WHERE f1.REVIEW_TYPE_CD = 'O' UNION SELECT f1.REVIEW_ID, f1.REVIEW_SCORE, f1.CREATE_USER AS owner_id FROM TB_TRMA_MOIM_REVIEW f1 WHERE f1.REVIEW_TYPE_CD = 'O' ) f_union GROUP BY owner_id ) e ON a.CREATE_USER = e.CREATE_USER WHERE a.USE_YN = 'Y' AND a.MOIM_START_DT > NOW()
AND ( a.MOIM_TITLE LIKE CONCAT('%', #{keyword}, '%') OR a.MOIM_DSCR LIKE CONCAT('%', #{keyword}, '%') )
AND c.CATE_CD = #{cateCd}
LIMIT 10 OFFSET #{offset}

SELECT CREATE_USER
FROM TB_TRMA_MOIM_LIST
WHERE MOIM_ID = #{moimId}

mapper.update:
UPDATE TB_TRMA_MOIM_LIST
SET MOIM_IMG_URL = (
    SELECT t.FIRST_IMAGE
    FROM TB_TRMA_MOIM_CALENDAR c
    LEFT JOIN TB_TRMA_TOUR_LIST t ON c.TOUR_ID = t.TOUR_ID
    WHERE c.MOIM_ID = #{moimId}
    ORDER BY c.START_DT ASC, c.RMKS ASC
    LIMIT 1
)
WHERE MOIM_ID = #{moimId}

UPDATE TB_TRMA_MOIM_LIST
SET MOIM_END_DT = #{moimEndDt}
    ,UPDATE_USER = #{userId}
    ,UPDATE_DT = CURRENT_TIMESTAMP
WHERE MOIM_ID = #{moimId}

UPDATE TB_TRMA_MOIM_MEMBER
SET STATE_CD = #{stateCd}
    ,UPDATE_USER = #{userId}
    ,UPDATE_DT = CURRENT_TIMESTAMP
WHERE MOIM_ID = #{moimId}
    AND USER_ID = #{targetUserId}

mapper.delete:
DELETE FROM TB_TRMA_MOIM_MEMBER
WHERE MOIM_ID = #{moimId}
    AND USER_ID = #{targetUserId}

mapper.insert:
INSERT INTO TB_TRMA_MOIM_REVIEW ( REVIEW_ID ,MOIM_ID ,REVIEW_TYPE_CD ,REVIEW_TITLE ,REVIEW_CONTENT ,REVIEW_SCORE ,IMG_URLS ,MOIM_START_DT ,MOIM_END_DT
,USE_YN ,CREATE_USER ,CREATE_DT ,UPDATE_USER ,UPDATE_DT ) SELECT #{reviewId} ,#{moimId} ,'O' ,CONCAT(m.MOIM_TITLE, ' 후기') ,#{request.reviewContent} ,#{request.reviewScore} ,#{imgUrls} ,m.MOIM_START_DT ,m.MOIM_END_DT
,'Y' ,#{userId} ,CURRENT_TIMESTAMP ,#{userId} ,CURRENT_TIMESTAMP FROM TB_TRMA_MOIM_LIST m WHERE m.MOIM_ID = #{moimId}

mapper.update:
UPDATE TB_TRMA_MOIM_REVIEW
REVIEW_CONTENT_EN = #{reviewContentEn}, REVIEW_CONTENT_JA = #{reviewContentJa},
WHERE REVIEW_ID = #{reviewId}

UPDATE TB_TRMA_MOIM_LIST
MOIM_TITLE_EN = #{moimTitleEn}, MOIM_TITLE_JA = #{moimTitleJa}, MOIM_DSCR_EN = #{moimDscrEn}, MOIM_DSCR_JA = #{moimDscrJa},
WHERE MOIM_ID = #{moimId}
